import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"Storage troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/storage-issues.md","filePath":"troubleshooting/storage-issues.md"}'),d={name:"troubleshooting/storage-issues.md"};function i(r,e,c,l,n,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="storage-troubleshooting" tabindex="-1">Storage troubleshooting <a class="header-anchor" href="#storage-troubleshooting" aria-label="Permalink to &quot;Storage troubleshooting&quot;">​</a></h1><p>Ordered triage, the mount-refusal paths, the filesystem capability matrix, the A/B disk, and the write-back cache.</p><h2 id="ordered-triage" tabindex="-1">Ordered triage <a class="header-anchor" href="#ordered-triage" aria-label="Permalink to &quot;Ordered triage&quot;">​</a></h2><p>Run <code>disk-tool</code> and walk the menu, or use the classic spellings:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; lspci                     (PCI storage controllers present?)</span></span>
<span class="line"><span>ush&gt; ahci / ata / nvme         (family probe - the message names the fault)</span></span>
<span class="line"><span>ush&gt; dskstat                   (block instances registered? cache state)</span></span>
<span class="line"><span>ush&gt; lsblk                     (devices + partitions scanned?)</span></span>
<span class="line"><span>ush&gt; parted &lt;dev&gt;              (the partition table)</span></span>
<span class="line"><span>ush&gt; fatstat &lt;dev&gt;             (FAT statistics of a suspect volume)</span></span>
<span class="line"><span>ush&gt; fsck &lt;dev&gt;                (filesystem check - FAT32 only)</span></span>
<span class="line"><span>ush&gt; fatmount &lt;dev&gt; /mnt       (mount)</span></span>
<span class="line"><span>ush&gt; fstest                    (the VFS/fs assertion suite)</span></span></code></pre></div><h2 id="the-filesystem-capability-matrix" tabindex="-1">The filesystem capability matrix <a class="header-anchor" href="#the-filesystem-capability-matrix" aria-label="Permalink to &quot;The filesystem capability matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Filesystem</th><th>Read</th><th>Write</th><th>Notes</th></tr></thead><tbody><tr><td>ramfs</td><td>RW</td><td>RW</td><td>the rootfs; everything on it is volatile — only /etc and mounted volumes persist</td></tr><tr><td>FAT32</td><td>RW</td><td>RW</td><td>full write support (file creation, cluster allocation, chain extension, directory updates, deletion); caches the first FAT in memory</td></tr><tr><td>exFAT</td><td>RW</td><td>RW</td><td>dirty-flag warning on unclean mounts (<code>exfat: warning - volume was not cleanly unmounted</code>)</td></tr><tr><td>ext4</td><td><strong>RO</strong></td><td>—</td><td>read-only driver; refuses INCOMP feature bits, block sizes &gt; 64 KiB, odd inode sizes</td></tr><tr><td>ext2/3</td><td>RO</td><td>—</td><td>ext2 is a subset of ext4; ext3 journals replay is not performed — mount is best-effort RO</td></tr></tbody></table><p>Case sensitivity follows the backing fs (BUG-0179): FAT32/exFAT are case-insensitive; ramfs/ext4 are case-sensitive. VFS limits: 16 mounts, 64 fds, names 64 bytes, paths 256 bytes.</p><h2 id="mount-refusal-paths-what-each-refusal-means" tabindex="-1">Mount-refusal paths (what each refusal means) <a class="header-anchor" href="#mount-refusal-paths-what-each-refusal-means" aria-label="Permalink to &quot;Mount-refusal paths (what each refusal means)&quot;">​</a></h2><ul><li><code>vfs_mount: unknown fs type</code> — the type is not one of ramfs/fat32/exfat/ext4.</li><li><code>vfs_mount: parent path does not exist</code> / <code>mount point exists and is not a directory</code> — create the mountpoint (<code>mount &lt;type&gt; &lt;dev&gt; &lt;path&gt;</code> pre-creates it; <code>fatmount</code> deliberately does NOT — on fatmount failure the two-line honest message says the mountpoint was NOT created).</li><li><code>fat32: not a FAT32 volume (FAT12/16 detected)</code> / <code>invalid BPB</code> / <code>read boot sector failed rc=&lt;N&gt;</code> — the volume is not a mountable FAT32. <code>fatstat &lt;dev&gt;</code> shows the parsed BPB; the usual cause is the wrong device node (<code>lsblk</code>) — or the alignment-destroying heap regression (fixed; re-run <code>ata_dma_test</code> if you touched mem_heap.c).</li><li><code>fat32: FAT cache alloc failed</code> / <code>FAT read failed</code> — memory or medium.</li><li><code>ext4: not an ext4 volume (bad magic)</code> / <code>read superblock failed</code> — not ext4, or the superblock is beyond the driver&#39;s reach.</li><li><code>ext4: unsupported INCOMP feature bits 0x&lt;hex&gt; - mount refused</code> (and the block-size/inode-size/group-size guards) — the RO driver refuses features it cannot honor; mount a simpler volume.</li><li><code>exfat: invalid number_of_fats</code> — not an exFAT.</li><li><code>umount: target is busy - close open files first</code> — open fds hold it (open_count is tracked per node, BUG-0061).</li><li><code>umount: unmount nested mounts first</code> — children first (<code>mounts</code> shows nesting).</li><li><code>umount: cannot unmount the root filesystem</code> — by design.</li><li><code>mount: failed</code> after a <code>fatmount</code> — the honest two-line message ends with <code>no FAT32 partition on device or drive not present</code>.</li></ul><h2 id="the-classics" tabindex="-1">The classics <a class="header-anchor" href="#the-classics" aria-label="Permalink to &quot;The classics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th></tr></thead><tbody><tr><td>valid FAT32 volume refused (<code>invalid BPB</code>)</td><td>wrong device node, or the alignment-destroying heap regression (fixed; rerun <code>ata_dma_test</code> if you touched mem_heap.c)</td></tr><tr><td>write lost after reboot</td><td>it lived on ramfs — only /etc and mounted volumes persist</td></tr><tr><td>USB stick appears then vanishes</td><td>USB MSC detach path — <code>usb_hotplug_test</code> reproduces</td></tr><tr><td>ext4 mount of an ext2 volume</td><td>supported (ext2 is a subset); check <code>fsck</code>-class signals first — fsck itself is FAT32-only</td></tr><tr><td>wizard asks twice for the device name</td><td>by design — mkfs/abdisk/install paths require the retype + bare-<code>y</code> confirmation</td></tr><tr><td>A/B disk &quot;absent&quot; right after <code>abdisk</code></td><td>re-run <code>update status</code>; the wizard re-checks in a loop until the service sees it</td></tr><tr><td>fsck reports dirty after clean unmount</td><td>FSINFO/FAT mirror regression — report it; this class is a bug</td></tr><tr><td><code>blk: write to protected device ... REFUSED (ocire recovery disk)</code></td><td>whole-disk OCIRE protection — by design; modify that volume only from OCIRE <code>repair</code></td></tr><tr><td><code>blkcache: alloc FAILED - cache disabled (raw I/O)</code></td><td>the 64-slot cache could not allocate; the system continues uncached (slower but correct)</td></tr><tr><td><code>virtio-blk: write rejected (device is read-only)</code></td><td>the QEMU drive was attached <code>readonly=on</code> — by design</td></tr><tr><td>ATAPI device on an AHCI port</td><td><code>&lt;port&gt;: ATAPI (not supported)</code> — declared limit</td></tr></tbody></table><h2 id="the-a-b-disk-—-layout-and-repair" tabindex="-1">The A/B disk — layout and repair <a class="header-anchor" href="#the-a-b-disk-—-layout-and-repair" aria-label="Permalink to &quot;The A/B disk — layout and repair&quot;">​</a></h2><p>Layout created by <code>abdisk &lt;dev&gt;</code> (destructive; re-runs <code>ota_ab_rescan()</code> afterwards):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p1 boot/flags 32 MB FAT32   /boot/next_B, /boot/ok_B, /boot/bootfail_B, grub.cfg</span></span>
<span class="line"><span>p2 slot A      128 MB FAT32 /boot/opencube.elf, /etc, /docs...</span></span>
<span class="line"><span>p3 slot B      128 MB FAT32 same structure as slot A</span></span>
<span class="line"><span>p4 /data       rest  FAT32 user data, downloaded packages</span></span></code></pre></div><ul><li><strong>Missing A/B disk</strong> is the #3 OTA silent failure: <code>update status</code> lacks <code>A/B disk: present</code>; <code>update</code> reports <code>update: cannot determine target slot (not booted from A/B?)</code>.</li><li><strong>Repair</strong>: <code>lsblk</code> → pick the device → <code>abdisk &lt;dev&gt;</code> (classic, or the disk-tool wizard&#39;s guarded path: it asks the device, asks you to RETYPE the exact name, warns, and requires a bare <code>y</code>). The chain reports its own step failures (<code>abdisk: failed to write partition table</code>, <code>mkfs.fat32 failed on p&lt;N&gt;</code>, ... — the first one is the real one).</li><li>Rollback semantics: <code>rollback</code> clears the flags; the boot menu&#39;s <code> rollback</code> label means <code>next_B</code> + <code>bootfail_B</code> forced slot A.</li><li>Boot-attempt budget: <code>/boot/grub/grubenv</code> <code>ab_attempts</code>, max 3.</li></ul><p>See <a href="./boot-failures.html">boot-failures.md</a> §6 for the slot-selection state machine.</p><h2 id="the-64-slot-lru-write-back-cache" tabindex="-1">The 64-slot LRU write-back cache <a class="header-anchor" href="#the-64-slot-lru-write-back-cache" aria-label="Permalink to &quot;The 64-slot LRU write-back cache&quot;">​</a></h2><p>The block layer keeps a 64-slot (64×512 B = 32 KiB) LRU <strong>write-back</strong> cache: <code>{dev_idx, lba, data[512], dirty, last_used}</code> with stats <code>{hits, misses, evicts, writebacks, used}</code> (<code>dskstat</code> shows the picture).</p><p>What this means for you:</p><ul><li>Written data may sit in cache until eviction or a flush — run <code>sync</code> before power operations, unmounts you care about, and any experiment that resets the machine.</li><li><code>sync</code> drives the OS cache flush <strong>plus</strong> the per-device flush hook: ATA FLUSH CACHE, NVMe Flush (0x0A), virtio-blk FLUSH, AHCI FLUSH CACHE EXT, SCSI SYNCHRONIZE CACHE.</li><li>If the cache could not allocate (<code>blkcache: alloc FAILED - cache disabled (raw I/O)</code>), writes go straight through (correct, slower).</li></ul><h2 id="the-destructive-paths" tabindex="-1">The destructive paths <a class="header-anchor" href="#the-destructive-paths" aria-label="Permalink to &quot;The destructive paths&quot;">​</a></h2><p><code>mkfs.*</code>, <code>abdisk</code>, <code>install</code> destroy data. In the wizards they are guarded (retype the device name, then a bare <code>y</code> — only <code>y</code>/<code>Y</code> answers yes); through classic/direct dispatch they run immediately — exactly like the historical commands — so scripts keep their semantics. <strong>Double-check the device name against <code>lsblk</code> before the classic forms.</strong> <code>fs_mount_test &lt;device&gt;</code> also formats its target. The installer chain (<code>install &lt;device&gt;</code>, ≥ 64 MiB, MBR ≤ 2 TiB) and <code>grub-install</code> (MBR gap ≥ core.img size) report step-by-step failures — <a href="./error-catalog.html">error-catalog.md</a> §5.4.</p><h2 id="driver-level-failure-strings" tabindex="-1">Driver-level failure strings <a class="header-anchor" href="#driver-level-failure-strings" aria-label="Permalink to &quot;Driver-level failure strings&quot;">​</a></h2><ul><li>AHCI: <code>ahci: issue fail (PxIS.TFE)</code>, <code>(PxTFD.ERR)</code>, <code>ahci: issue TIMEOUT CI=...</code>, <code>&lt;port&gt;: IDENTIFY failed</code>, <code>ahci: BAR5 invalid</code>.</li><li>ATA: <code>ata: PIO read DRQ timeout lba=&lt;n&gt;</code>, <code>atadma: xfer FAIL rc=&lt;n&gt;</code>.</li><li>NVMe: <code>nvme: BAR0 invalid</code>, <code>disable timeout ... retrying</code>, <code>ready timeout, resetting and retrying</code>, <code>unsupported formatted LBA size (only 512B supported)</code>, <code>Identify Controller/Namespace failed</code>.</li><li>virtio-blk: <code>no legacy PCI device found (modern-only devices not supported)</code>, <code>used-ring poll timeout</code>.</li><li>USB MSC: <code>msc: CBW bulk out failed</code>, <code>msc: CSW bad signature or tag</code>, <code>usb-msc: device not ready</code>.</li></ul><p>Full list with responses: <a href="./error-catalog.html">error-catalog.md</a> §6.5.</p><h2 id="reading-the-probes" tabindex="-1">Reading the probes <a class="header-anchor" href="#reading-the-probes" aria-label="Permalink to &quot;Reading the probes&quot;">​</a></h2><ul><li><code>dskstat</code> — which block instances registered, plus the cache picture (<code>hits/misses/evicts/writebacks/used</code> for the 64-slot LRU). Zero instances = no storage driver bound (see the driver strings below / QEMU flags).</li><li><code>lsblk</code> — devices and scanned partitions; the authoritative source for device names (every destructive command takes these names exactly).</li><li><code>parted &lt;dev&gt;</code> — the MBR/GPT table view.</li><li><code>fatstat &lt;dev&gt;</code> — the parsed BPB of a suspect FAT32: if the fields (bytes/sector, sectors/cluster, reserved, FAT size, root cluster) look insane, you are looking at the wrong device or a corrupt volume.</li><li><code>fsck &lt;dev&gt;</code> — FAT32-only check; verdicts are per-check <code>FAIL (&lt;detail&gt;)</code> lines with a final summary (the dirty-cluster check prints <code>cluster count mismatch: counted &lt;A&gt; ...</code>).</li></ul><h2 id="qemu-storage-flags-cheat-sheet" tabindex="-1">QEMU storage flags cheat sheet <a class="header-anchor" href="#qemu-storage-flags-cheat-sheet" aria-label="Permalink to &quot;QEMU storage flags cheat sheet&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Flag</th><th>Notes</th></tr></thead><tbody><tr><td>plain writable disk</td><td><code>-drive file=hd.img,format=raw</code></td><td>shows as IDE/ATA</td></tr><tr><td>virtio-blk fast path</td><td><code>-drive file=hd.img,if=virtio,format=raw</code></td><td>legacy PCI device required (modern-only refused)</td></tr><tr><td>AHCI</td><td><code>-device ahci</code> + <code>-drive ...</code></td><td>ATAPI devices print <code>not supported</code></td></tr><tr><td>NVMe</td><td><code>-drive file=nvme.img,if=none,id=nvme0 -device nvme,drive=nvme0,serial=ns1</code></td><td>only 512B LBA size supported</td></tr><tr><td>read-only intent</td><td><code>readonly=on</code></td><td>writes print the honest <code>virtio-blk: write rejected</code></td></tr><tr><td>USB stick</td><td><code>-usb -device usb-storage,drive=u0</code></td><td>detach/reattach via <code>usb_hotplug_test</code></td></tr></tbody></table><p>Remember <code>-snapshot</code> (the default in the <code>run-*</code> make targets) means writes do not persist; <code>run-bios-persist</code> / <code>run-uefi-persist</code> turn it off so <code>/etc/opencube.conf</code> edits land in <code>build/etc.img</code>.</p><h2 id="partition-table-notes" tabindex="-1">Partition-table notes <a class="header-anchor" href="#partition-table-notes" aria-label="Permalink to &quot;Partition-table notes&quot;">​</a></h2><ul><li>MBR only on the install path (<code>install</code> refuses &gt; 2 TiB).</li><li>GPT is parsed for display (<code>parted</code>) — the in-system installer writes MBR layouts.</li><li>The OCIRE recovery disk&#39;s 0xEE &quot;shadow&quot; MBR entry with no GPT header is a deliberate disguise: normal GPT tooling ignores the 16 MiB FAT12 volume behind it, and the whole-disk write protection keeps it that way.</li><li>Partition children of the A/B disk (p2/p3) are slot-consumed — they cannot register their own boot entries.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./error-catalog.html">error-catalog.md</a> §5.2-§5.4, §6.5 — every message</li><li><a href="./../manual/filesystems.html">../manual/filesystems.md</a> — the user guide</li><li><a href="./../manual/update-ota.html">../manual/update-ota.md</a> — the A/B story</li><li><a href="./boot-failures.html">boot-failures.md</a> — the boot side of A/B</li></ul>`,35)])])}const m=t(d,[["render",i]]);export{p as __pageData,m as default};
